# area: paramspec_concatenate
# hypothesis: Wrapping a ParamSpec-generic callable inside a generic class Retry[P, R] after a Concatenate-based decorator keeps the parameter list, so the nested call type-checks and returns list[str] at runtime.
from typing import Callable, Concatenate, Generic, ParamSpec, TypeVar, assert_type, reveal_type

P = ParamSpec('P')
R = TypeVar('R')


def with_ctx(fn: Callable[Concatenate[int, P], R]) -> Callable[P, R]:
    def inner(*args: P.args, **kwargs: P.kwargs) -> R:
        return fn(7, *args, **kwargs)
    return inner


class Retry(Generic[P, R]):
    def __init__(self, fn: Callable[P, R], times: int) -> None:
        self.fn = fn
        self.times = times

    def __call__(self, *args: P.args, **kwargs: P.kwargs) -> list[R]:
        return [self.fn(*args, **kwargs) for _ in range(self.times)]


def describe(ctx: int, name: str, *, loud: bool = False) -> str:
    return str(ctx) + ':' + name + ('!' if loud else '')


base = with_ctx(describe)
reveal_type(base)
assert_type(base('a'), str)
retry = Retry(base, 2)
reveal_type(retry)
out = retry('b', loud=True)
assert_type(out, list[str])
print(out)
print(Retry(with_ctx(describe), 1)('c'))
